export async function provisionCustomerDatabase(customerId: string, customerName: string): Promise<string> {
  const dbName = `customer_${customerId.replace(/-/g, '_')}`;

  // 1. Connect to postgres database to create new database
  const adminPool = new Pool({ connectionString: process.env.DATABASE_URL });
  await adminPool.query(`CREATE DATABASE "${dbName}"`);
  await adminPool.end();

  // 2. Connect to new database and run migrations
  const customerPool = new Pool({ 
    connectionString: buildCustomerConnectionString(dbName) 
  });
  await runCustomerMigrations(customerPool);
  await customerPool.end();

  return dbName;
}
```

