```typescript
import { db as controlPlane } from '@/db/control-plane/connection';
import { customers, memberships } from '@/db/control-plane/schema';

export async function getCustomerConnection(
  userId: string,
  customerId: string
): Promise<CustomerDb> {
  // 1. Verify user has access to this customer through organization membership
  const customer = await controlPlane
    .select()
    .from(customers)
    .innerJoin(memberships, eq(memberships.organizationId, customers.organizationId))
    .where(and(
      eq(customers.id, customerId),
      eq(memberships.userId, userId),
      eq(customers.status, 'active')
    ))
    .limit(1);

  if (!customer.length) {
    throw new CustomerAccessDeniedError(customerId);
  }

  // 2. Return connection to customer's database
  return createCustomerDbConnection(customer[0].databaseName);
}
```

