Create `src/lib/retrieval.ts`:

```typescript
import { sql } from 'drizzle-orm';

export interface RetrievalResult {
  chunk: Chunk;
  sourceItem: SourceItem;
  similarity: number;
}

export async function retrieveContext(
  customerDb: CustomerDb,
  query: string,
  options: RetrievalOptions = {}
): Promise<RetrievalResult[]> {
  const { limit = 10, threshold = 0.7 } = options;

  // Generate embedding for query
  const queryEmbedding = await generateEmbedding(query);

  // Perform vector similarity search
  const results = await customerDb
    .select({
      chunk: chunks,
      sourceItem: sourceItems,
      similarity: sql<number>`1 - (${chunks.embedding} <=> ${queryEmbedding})`,
    })
    .from(chunks)
    .innerJoin(sourceItems, eq(chunks.sourceItemId, sourceItems.id))
    .where(sql`1 - (${chunks.embedding} <=> ${queryEmbedding}) > ${threshold}`)
    .orderBy(sql`${chunks.embedding} <=> ${queryEmbedding}`)
    .limit(limit);

  return results;
}
```

