```typescript
async *streamSuggestions(context: SuggestionContext): AsyncGenerator<Suggestion> {
  const retrieved = await retrieveContext(this.customerDb, context.recentTranscript, {
    limit: 10,
    threshold: 0.7,
  });

  const prompt = buildSuggestionPrompt(context, retrieved);

  const stream = this.anthropic.messages.stream({
    model: 'claude-sonnet-4-20250514',
    max_tokens: 1024,
    messages: [{ role: 'user', content: prompt }],
  });

  let buffer = '';
  for await (const event of stream) {
    if (event.type === 'content_block_delta' && event.delta.type === 'text_delta') {
      buffer += event.delta.text;
      // Parse complete suggestions from buffer
      const parsed = extractCompleteSuggestions(buffer);
      for (const suggestion of parsed.complete) {
        yield suggestion;
      }
      buffer = parsed.remaining;
    }
  }
  // Yield any remaining suggestions
  if (buffer.trim()) {
    yield* parseFinalSuggestions(buffer);
  }
}
