export async function startCallSession(
  customerId: string,
  solutionId: string,
  meetingUrl: string
): Promise<{ success: true; callId: string } | { success: false; error: string }> {
  // 1. Authenticate and get customer connection
  const session = await requireAuth();
  const customerDb = await getCustomerConnection(session.user.id, customerId);

  // 2. Validate meetingUrl format (Meet/Zoom/Teams patterns)
  if (!isValidMeetingUrl(meetingUrl)) {
    return { success: false, error: 'Invalid meeting URL' };
  }

  // 3. Verify solution exists and belongs to this customer
  const solution = await customerDb.query.solutions.findFirst({ where: eq(solutions.id, solutionId) });
  if (!solution) {
    return { success: false, error: 'Solution not found' };
  }

  // 4. Create call record with consent_acknowledged = true
  const [call] = await customerDb.insert(calls).values({
    solutionId,
    meetingUrl,
    consentAcknowledged: true, // Critical: only set true because user checked the box
    botStatus: 'creating',
  }).returning();

  // 5. Create Recall.ai bot
  try {
    const bot = await createBot({
      meetingUrl,
      botName: 'Robin Assistant',
      webhookUrl: `${process.env.NEXT_PUBLIC_APP_URL}/api/webhooks/recall/transcript`,
      metadata: { callId: call.id, customerId, solutionId },
    });

    // 6. Update call with bot ID
    await customerDb.update(calls).set({ botId: bot.id, botStatus: 'joining' }).where(eq(calls.id, call.id));

    return { success: true, callId: call.id };
  } catch (error) {
    // Update call status to error
    await customerDb.update(calls).set({ botStatus: 'error' }).where(eq(calls.id, call.id));
    return { success: false, error: 'Failed to create meeting bot' };
  }
}
