export async function getUpcomingEventsWithMeetings(
  organizationId: string,
  options: { hoursAhead?: number } = {}
): Promise<CalendarEvent[]> {
  const { hoursAhead = 24 } = options;

  // Get Google connection for org
  const connection = await getIntegrationConnection(organizationId, 'google');
  if (!connection) return [];

  // Decrypt tokens and create OAuth client
  const tokens = await decryptTokens(connection.encryptedTokens);
  const oauth2Client = new google.auth.OAuth2();
  oauth2Client.setCredentials(tokens);

  // Query Calendar API
  const calendar = google.calendar({ version: 'v3', auth: oauth2Client });
  const now = new Date();
  const timeMax = new Date(now.getTime() + hoursAhead * 60 * 60 * 1000);

  const response = await calendar.events.list({
    calendarId: 'primary',
    timeMin: now.toISOString(),
    timeMax: timeMax.toISOString(),
    singleEvents: true,
    orderBy: 'startTime',
  });

  // Filter and transform events with meeting links
  return response.data.items
    ?.filter(event => event.conferenceData?.entryPoints?.length || event.hangoutLink)
    .map(event => ({
      id: event.id!,
      title: event.summary || 'Untitled',
      start: new Date(event.start?.dateTime || event.start?.date!),
      end: new Date(event.end?.dateTime || event.end?.date!),
      meetLink: event.hangoutLink || event.conferenceData?.entryPoints?.[0]?.uri || null,
      platform: detectPlatform(event),
    })) || [];
}
