export async function syncCustomerSource(sourceId: string): Promise<SyncResult> {
  const source = await getCustomerSource(sourceId);
  const adapter = getAdapter(source.provider);
  const tokens = await getIntegrationTokens(source.connectionId);

  let pageToken: string | undefined;
  let itemsProcessed = 0;

  do {
    const { items, nextPageToken } = await adapter.fetchContent(
      tokens, 
      source.selector,
      pageToken
    );

    for (const item of items) {
      // Check if already synced (by content hash)
      const existing = await findSourceItemByHash(item.contentHash);
      if (existing && existing.contentHash === item.contentHash) continue;

      // Normalize content
      const normalized = normalizeContent(item);

      // Chunk and embed
      const chunks = chunkText(normalized.text);
      for (const chunk of chunks) {
        const embedding = await generateEmbedding(chunk.text);
        await storeChunk(sourceItem.id, chunk, embedding);
      }

      itemsProcessed++;
    }

    pageToken = nextPageToken;
  } while (pageToken);

  return { itemsProcessed };
}
