## Integration Test Utilities

Create `src/test/db.ts` for throwaway database management:
```typescript
import { sql } from 'drizzle-orm';
import { drizzle } from 'drizzle-orm/node-postgres';
import { Pool } from 'pg';
import { randomBytes } from 'node:crypto';

import { requireEnv } from '@/db/env';

/**
 * Creates a throwaway test database with a random suffix.
 * Returns connection pool and cleanup function.
 */
export async function createTestDatabase(): Promise<{
  pool: Pool;
  db: ReturnType<typeof drizzle>;
  databaseName: string;
  cleanup: () => Promise<void>;
}> {
  const baseUrl = requireEnv('DATABASE_URL');
  const suffix = randomBytes(4).toString('hex');
  const databaseName = `robin_test_${suffix}`;

  // Connect to the control-plane database to create the test database
  const adminPool = new Pool({ connectionString: baseUrl });
  await adminPool.query(`CREATE DATABASE ${databaseName}`);
  await adminPool.end();

  // Connect to the new test database
  const testUrl = baseUrl.replace(/\/robin$/, `/${databaseName}`);
  const pool = new Pool({ connectionString: testUrl });

  // Enable pgvector extension
  await pool.query('CREATE EXTENSION IF NOT EXISTS vector');

  const db = drizzle(pool);

  const cleanup = async (): Promise<void> => {
    await pool.end();
    const cleanupPool = new Pool({ connectionString: baseUrl });
    // Force disconnect any remaining connections
    await cleanupPool.query(`
      SELECT pg_terminate_backend(pid) 
      FROM pg_stat_activity 
      WHERE datname = '${databaseName}' AND pid <> pg_backend_pid()
    `);
    await cleanupPool.query(`DROP DATABASE IF EXISTS ${databaseName}`);
    await cleanupPool.end();
  };

  return { pool, db, databaseName, cleanup };
}

