import { describe, it, expect, afterAll } from 'vitest';
import { sql } from 'drizzle-orm';

import { createTestDatabase } from '@/test/db';

describe('Database Connection', () => {
  let cleanup: () => Promise<void>;

  afterAll(async () => {
    if (cleanup) await cleanup();
  });

  it('creates and drops a throwaway test database', async () => {
    const result = await createTestDatabase();
    cleanup = result.cleanup;

    // Verify we can query the test database
    const queryResult = await result.db.execute(sql`SELECT 1 as value`);
    expect(queryResult.rows[0]).toEqual({ value: 1 });

    // Verify pgvector is available
    const extResult = await result.db.execute(
      sql`SELECT extname FROM pg_extension WHERE extname = 'vector'`
    );
    expect(extResult.rows).toHaveLength(1);
  });
});
```

## File Structure

```
robin/
├── vitest.config.ts           # Vitest configuration
├── src/
│   ├── test/
│   │   ├── setup.ts           # Test setup (env loading)
│   │   └── db.ts              # Database test utilities
│   └── db/
│       └── control-plane/
│           └── connection.test.ts  # Example colocated test
```

## Key Considerations

1. **Colocated tests**: Tests live next to the code they test as `*.test.ts` files, per project convention
2. **Single fork execution**: Database tests run sequentially to avoid connection pool conflicts
3. **Throwaway databases**: Each test suite can create its own database, completely isolated
4. **Dev container Postgres**: Tests use the same local server defined in `.devcontainer/post-start.sh`
5. **Path aliases**: `vite-tsconfig-paths` reads `tsconfig.json` paths for `@/` alias support
6. **Environment loading**: `.env` is loaded via `process.loadEnvFile()` (Node.js built-in) in setup file
